const $=s=>document.querySelector(s);
function safe(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
async function request(url,body){const r=await fetch(url,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d;}
function status(s,err=false){$('#status').textContent=s;$('#status').style.color=err?'#a61b27':'#1c7a54';}
async function init(){const p=await request('/api/providers');$('#provider').innerHTML=p.filter(x=>!['csv','xml'].includes(x.id)).map(x=>`<option value="${safe(x.id)}">${safe(x.name)} — ${safe(x.mode)}</option>`).join('');await refresh();}
async function refresh(){const [cs,ps,bs]=await Promise.all(['/api/connections','/api/products','/api/batches'].map(u=>request(u)));$('#connections').innerHTML=cs.length?cs.map(x=>`<div class="result"><strong>${safe(x.name)}</strong> <span class="tag">${safe(x.status)}</span><div class="muted">${safe(x.provider_id)} · mock · no remote test performed</div></div>`).join(''):'<p class="muted">No demo connections yet.</p>';$('#products').innerHTML=ps.length?`<table><thead><tr><th>SKU</th><th>Product</th><th>Color</th><th>Brand</th><th>Indicative price</th></tr></thead><tbody>${ps.map(x=>`<tr><td>${safe(x.sku)}</td><td>${safe(x.name)}</td><td>${safe(x.color)}</td><td>${safe(x.brand)}</td><td>${x.sale_price?'$'+safe(x.sale_price):'Quote only'}</td></tr>`).join('')}</tbody></table>`:'<p class="muted">No published products yet.</p>';$('#batches').innerHTML=bs.length?bs.map(b=>{let d=b.data;let bad=d.rows.filter(r=>!r.eligible);return `<div class="result"><strong>${safe(b.id.slice(0,8))}</strong> <span class="tag">${safe(b.state)}</span> &middot; ${safe(d.accepted)} eligible, ${safe(d.rejected)} rejected <div class="muted">Mapping: ${safe(JSON.stringify(d.mapping))}</div><div class="muted">${safe(bad.slice(0,5).map(x=>'Row '+x.row+': '+x.errors.join('; ')).join(' | ')||'No validation errors')}</div><button class="dark" data-batch="${safe(b.id)}" ${b.state==='published'?'disabled':''}>Publish valid rows</button></div>`}).join(''):'<p class="muted">No staged imports yet.</p>';document.querySelectorAll('[data-batch]').forEach(btn=>btn.onclick=async()=>{try{let d=await request(`/api/imports/${btn.dataset.batch}/publish`,{});status(`${d.published} rows published; ${d.held} held. Synthetic demonstration only.`);await refresh()}catch(e){status(e.message,true)}});}
$('#add').onclick=async()=>{try{const d=await request('/api/connections',{provider_id:$('#provider').value,name:$('#connectionName').value});status(d.message);await refresh()}catch(e){status(e.message,true)}};
$('#preview').onclick=async()=>{const f=$('#file').files[0];if(!f){status('Select a .csv or .xml file',true);return}if(f.size>2_000_000){status('File too large',true);return}try{const format=f.name.toLowerCase().endsWith('.xml')?'xml':'csv';const d=await request('/api/imports/preview',{format,content:await f.text()});$('#previewInfo').innerHTML=`<p>${d.data.accepted} valid · ${d.data.rejected} rejected</p>`;
  const keys=Object.keys(d.data.rows[0]?.source||{});
  $('#mappingControls').innerHTML='<h3>Field mapping (editable)</h3>'+Object.keys(d.data.mapping).map(field=>`<label for="map_${safe(field)}">${safe(field)}</label><select id="map_${safe(field)}" data-map="${safe(field)}"><option value="">— Ignore —</option>${keys.map(k=>`<option value="${safe(k)}" ${d.data.mapping[field]===k?'selected':''}>${safe(k)}</option>`).join('')}</select>`).join('')+'<button id="remap" class="dark">Preview with this mapping</button>';
  $('#remap').onclick=async()=>{try{let mapping={};document.querySelectorAll('[data-map]').forEach(el=>mapping[el.dataset.map]=el.value||null);const dd=await request('/api/imports/preview',{format,content:await f.text(),mapping});status(`New mapped batch staged: ${dd.data.accepted} valid, ${dd.data.rejected} rejected.`);await refresh()}catch(e){status(e.message,true)}};
  status('Staged. Review the mapping and errors below.');await refresh()}catch(e){status(e.message,true)}};
init().catch(e=>status(e.message,true));
